namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile was updated."),
            CreateNotification("New comment on your post."),
        });
    }

    /// <summary>Returns all notifications available at this moment.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications added after the given timestamp.</summary>
    public List<Notification> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Timestamp > since).ToList();
        }
    }

    /// <summary>Simulates a new notification arriving (called by the background generator).</summary>
    public void AddRandom()
    {
        string[] messages =
        [
            "You have a new follower.",
            "Someone liked your photo.",
            "Reminder: meeting at 3 PM.",
            "Server deployment succeeded.",
            "Your subscription is expiring soon.",
            "New message from support.",
            "Weekly report is ready.",
        ];

        var message = messages[Random.Shared.Next(messages.Length)];
        lock (_lock)
        {
            _notifications.Add(CreateNotification(message));
        }
    }

    private Notification CreateNotification(string message)
        => new(Interlocked.Increment(ref _nextId), message, DateTime.UtcNow);
}

